window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51be6b32a156e1fb"]={"versions": [{"id": "FIG-51be6b32a156e1fb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Zuschnitts bzw. Tailorings von Datenelementen im Kontext des AUTOSAR Standardization Template (TPS_StandardizationTemplate). Das Diagramm modelliert Spezialisierungen generischer Spezifikationselement-Referenzen und Gültigkeitsbereiche für Datenelementformate sowie deren Einschränkungen samt zugeordneter Schweregrade.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SpecElementReference</code>: Basisklasse (abgeleitet von <code>Identifiable</code>), besitzt das optionale Attribut <code>alternativeName :String [0..1]</code>.</li>\n<li><code>SpecElementScope</code>: Spezialisiert <code>SpecElementReference</code> via Generalisierung (Vererbungspfeil mit geschlossener Spitze); deklariert das optionale Attribut <code>inScope :Boolean [0..1]</code>.</li>\n<li><code>DataFormatElementScope</code> / <code>DataFormatElementReference</code>: Spezialisiert <code>SpecElementScope</code> via Generalisierung. Besitzt eine gerichtete Referenz/Assoziation (gestrichelte Linie mit offener Pfeilspitze) mit der Rollenbezeichnung <code>+restriction</code> und Multiplizität <code>0..*</code> auf <code>RestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Ziel der <code>+restriction</code>-Referenz; kapselt das Attribut <code>severity :SeverityEnum</code>.</li>\n<li><code>SeverityEnum</code>: Enumeration (<code>«enumeration»</code>) mit den Literalen <code>info</code>, <code>warning</code> und <code>error</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen, Zustandsübergänge oder Sequenzabläufe. Die Instanzen bilden eine hierarchische Konfigurations- und Tailoring-Struktur ab, bei der Datenelementdefinitionen über Rollen- und Gültigkeitsbereiche referenziert und bedarfsweise mit Einschränkungsregeln inklusive Meldeschweregrad versehen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für AUTOSAR-Standardisierungswerkzeuge und Validatoren. Das Attribut <code>inScope</code> steuert die Aktivierung eines Elements im jeweiligen Tailoring-Profil. Die Rolle <code>+restriction</code> ermöglicht das Anbinden von Restriktionen mit definierter Granularität (<code>info</code>, <code>warning</code>, <code>error</code>) zur automatisierten Überprüfung von Konformitätsregeln. Attributnamen, Typen und Kardinalitäten (<code>[0..1]</code>, <code>0..*</code>) sind bindend umzusetzen.</p>"}, {"id": "FIG-e875837fe8251016", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Zuschnitts bzw. Tailorings von Datenelementen im Kontext des AUTOSAR Standardization Template (TPS_StandardizationTemplate). Das Diagramm modelliert Spezialisierungen generischer Spezifikationselement-Referenzen und Gültigkeitsbereiche für Datenelementformate sowie deren Einschränkungen samt zugeordneter Schweregrade.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SpecElementReference</code>: Basisklasse (abgeleitet von <code>Identifiable</code>), besitzt das optionale Attribut <code>alternativeName: String [0..1]</code>.</li>\n<li><code>SpecElementScope</code>: Spezialisiert <code>SpecElementReference</code> via Generalisierung (Vererbungspfeil mit geschlossener Spitze); deklariert das optionale Attribut <code>inScope: Boolean [0..1]</code>.</li>\n<li><code>DataFormatElementScope</code> / <code>DataFormatElementReference</code>: Spezialisiert <code>SpecElementScope</code> via Generalisierung. Besitzt eine gerichtete Referenz/Assoziation (gestrichelte Linie mit offener Pfeilspitze) mit der Rollenbezeichnung <code>+restriction</code> und Multiplizität <code>0..*</code> auf <code>RestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Ziel der <code>+restriction</code>-Referenz; kapselt das Attribut <code>severity: SeverityEnum</code>.</li>\n<li><code>SeverityEnum</code>: Enumeration (<code>«enumeration»</code>) mit den Literalen <code>info</code>, <code>warning</code> und <code>error</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen, Zustandsübergänge oder Sequenzabläufe. Die Instanzen bilden eine hierarchische Konfigurations- und Tailoring-Struktur ab, bei der Datenelementdefinitionen über Rollen- und Gültigkeitsbereiche referenziert und bedarfsweise mit Einschränkungsregeln inklusive Meldeschweregrad versehen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für AUTOSAR-Standardisierungswerkzeuge und Validatoren. Das Attribut <code>inScope</code> steuert die Aktivierung eines Elements im jeweiligen Tailoring-Profil. Die Rolle <code>+restriction</code> ermöglicht das Anbinden von Restriktionen mit definierter Granularität (<code>info</code>, <code>warning</code>, <code>error</code>) zur automatisierten Überprüfung von Konformitätsregeln. Attributnamen, Typen und Kardinalitäten (<code>[0..1]</code>, <code>0..*</code>) sind bindend umzusetzen.</p>"}, {"id": "FIG-879de8e52ed725ac", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Zuschnitts bzw. Tailorings von Datenelementen im Kontext des AUTOSAR Standardization Template (TPS_StandardizationTemplate). Das Diagramm modelliert Spezialisierungen generischer Spezifikationselement-Referenzen und Gültigkeitsbereiche für Datenelementformate sowie deren Einschränkungen samt zugeordneter Schweregrade.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SpecElementReference</code>: Basisklasse (abgeleitet von <code>Identifiable</code>), besitzt das optionale Attribut <code>alternativeName: String [0..1]</code>.</li>\n<li><code>SpecElementScope</code>: Spezialisiert <code>SpecElementReference</code> via Generalisierung (Vererbungspfeil mit geschlossener Spitze); deklariert das optionale Attribut <code>inScope: Boolean [0..1]</code>.</li>\n<li><code>DataFormatElementScope</code> / <code>DataFormatElementReference</code>: Spezialisiert <code>SpecElementScope</code> via Generalisierung. Besitzt eine gerichtete Referenz/Assoziation (gestrichelte Linie mit offener Pfeilspitze) mit der Rollenbezeichnung <code>+restriction</code> und Multiplizität <code>0..*</code> auf <code>RestrictionWithSeverity</code>.</li>\n<li><code>RestrictionWithSeverity</code>: Ziel der <code>+restriction</code>-Referenz; kapselt das Attribut <code>severity: SeverityEnum</code>.</li>\n<li><code>SeverityEnum</code>: Enumeration (<code>«enumeration»</code>) mit den Literalen <code>info</code>, <code>warning</code> und <code>error</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen, Zustandsübergänge oder Sequenzabläufe. Die Instanzen bilden eine hierarchische Konfigurations- und Tailoring-Struktur ab, bei der Datenelementdefinitionen über Rollen- und Gültigkeitsbereiche referenziert und bedarfsweise mit Einschränkungsregeln inklusive Meldeschweregrad versehen werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell für AUTOSAR-Standardisierungswerkzeuge und Validatoren. Das Attribut <code>inScope</code> steuert die Aktivierung eines Elements im jeweiligen Tailoring-Profil. Die Rolle <code>+restriction</code> ermöglicht das Anbinden von Restriktionen mit definierter Granularität (<code>info</code>, <code>warning</code>, <code>error</code>) zur automatisierten Überprüfung von Konformitätsregeln. Attributnamen, Typen und Kardinalitäten (<code>[0..1]</code>, <code>0..*</code>) sind bindend umzusetzen.</p>"}], "trans": [{"from": "FIG-51be6b32a156e1fb", "to": "FIG-e875837fe8251016", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Attributdefinitionen in <code>SpecElementReference</code>, <code>SpecElementScope</code> und <code>RestrictionWithSeverity</code>: Leerzeichen vor dem Doppelpunkt des Typbezeichners entfernt (<code>:String</code> zu <code>: String</code>, <code>:Boolean</code> zu <code>: Boolean</code>, <code>:SeverityEnum</code> zu <code>: SeverityEnum</code>).</li>\n</ul>"}, {"from": "FIG-e875837fe8251016", "to": "FIG-879de8e52ed725ac", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
